


def merge(lst1:list,lst2:list):
    i:int =0
    j:int =0 

    resultat:list = []
    while i<len(lst1) and j<len(lst2):
        if lst1[i] <= lst2[j]:
            resultat.append(lst1[i])
            i += 1
        else:
            resultat.append(lst2[j])
            j += 1
    resultat.extend(lst1[i:])
    resultat.extend(lst2[j:])



    return resultat




def mergesort(lst:list):
    if len(lst)<2:
        return lst.copy()
    mid = len(lst)//2
    left = mergesort(lst[:mid])
    right = mergesort(lst[mid:])



    return merge(left,right)



def tri_bule(lst:list):

    for i in range(len(lst)):
        for j in range(i,len(lst)):
            if lst[i] > lst[j]:
                temp = lst[i]
                lst[i] = lst[j]
                lst[j] = temp 



def selection_sort_final(lst):
    n = len(lst)
    for i in range(n // 2):
        min_idx = i
        max_idx = i
        for j in range(i + 1, n - i):
            if lst[j] < lst[min_idx]:
                min_idx = j
            elif lst[j] > lst[max_idx]:
                max_idx = j

        if min_idx == i and max_idx == n - i - 1:
            continue

        lst[i], lst[min_idx] = lst[min_idx], lst[i]
        if max_idx == i:
            max_idx = min_idx
        lst[n - i - 1], lst[max_idx] = lst[max_idx], lst[n - i - 1]
    return lst














